/// <summary>
/// Extension class for PurchPurchaseOrderController.
/// </summary>
[ExtensionOf(classStr(PurchPurchaseOrderController))]
final class METPurchPurchaseOrderController_Extension
{


}

Method.Source:
    /// <summary>
    /// Updating the email settings based on vendor site settings.
    /// </summary>
    /// <param name = "_activity">_activity</param>
    /// <returns>boolean</returns>
    protected internal boolean validateReportPrintJobSettingsEmailTo(SysInstrumentationActivity _activity)
    {
        PrintMgmtReportRun printMgmtReportRunLocal = formLetterReport.parmReportRun();

        if (printMgmtReportRunLocal.next())
        {
            SRSPrintDestinationSettings printSettings = printMgmtReportRunLocal.settingDetail().parmPrintJobSettings();

            if (printSettings.printMediumType() == SRSPrintMediumType::Email)
            {
                str emailTo = printSettings.emailTo();

                if (!emailTo)
                {
                    printSettings.emailTo(METPurchTable::getIGHPOEmailAddress(vendPurchOrderJour.PurchId));
                }

                PurchTable purchTable = PurchTable::find(vendPurchOrderJour.PurchId);
                MetPurchTable metPurchTable = MetPurchTable::find(purchTable.PurchId);

                NumberOfRecords recordCnt = VendPurchOrderJour::numberOfPurchaseOrderVersions(purchTable);
                METMultiSelectStringValue multiStrVal;

                if (recordCnt == 0)
                {
                    multiStrVal = metPurchTable.POSubMode;
                }
                else
                {
                    multiStrVal = metPurchTable.POChngSubMode;
                }

                if (PurchFormLetter::getPOSubMode(multiStrVal, enum2Str(METPOSubMode::Email)))
                {
                    METVendSiteSettingsSetup metVendSiteSettingsSetup;
                
                    select firstonly POEmailAddresses, RecId from  metVendSiteSettingsSetup
                        where metVendSiteSettingsSetup.AssignedSite == purchTable.InventSiteId
                        && metVendSiteSettingsSetup.AssignedWH == purchTable.InventLocationId
                        && metVendSiteSettingsSetup.AssignedVendorAccount == purchTable.OrderAccount;

                    if (metVendSiteSettingsSetup.POEmailAddresses)
                    {
                        printSettings.emailTo(metVendSiteSettingsSetup.POEmailAddresses);
                    }
                }
            }

            printMgmtReportRunLocal.reset();
        }

        return next validateReportPrintJobSettingsEmailTo(_activity);
    }

    /// <summary>
    /// Prepares the contract before the report is run.
    /// </summary>
    protected void modifyContract()
    {
        PurchTable purchTable = PurchTable::find(vendPurchOrderJour.PurchId);

        if (purchTable)
        {
            if (purchTable.vendTable_OrderAccount().VendGroup == METConstants::ImportPOVendorGroup && purchTable.PurchPoolId == METConstants::ImportPOPoolId)
            {
                this.parmReportContract().parmReportName(ssrsReportStr(METPurchPurchaseOrder, ReportImport));
                this.parmReportName(ssrsReportStr(METPurchPurchaseOrder, ReportImport));
            
            }
            else
            {
                this.parmReportContract().parmReportName(ssrsReportStr(METPurchPurchaseOrder, ReportTrade));
                this.parmReportName(ssrsReportStr(METPurchPurchaseOrder, ReportTrade));
            
            }
        }

        next modifyContract();
    }
